import type { NextApiRequest, NextApiResponse } from 'next';

// ❌ OLD: The server buffers the entire payload in memory before returning,
// causing poor perceived latency for LLM or batch processing.
export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const fullText = await generateCompleteText();
  res.status(200).json({ result: fullText });
}

export const dynamic = 'force-dynamic';

export async function GET() {
  // ✅ NEW: ReadableStream pushes chunks as they become available
  const stream direct = new ReadableStream({
    async start(controller) {
      const encoder = new TextEncoder();
      for (let i = 0; i < 5; i++) {
        controller.enqueue(encoder.encode(`data: Chunk ${i}\n\n`));
        await new Promise((resolve) => setTimeout(resolve, 500));
      }
      controller.close();
    }
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive'
    }
  });
}
